def deco(f):
    def wrapper(*a, **k):
        return f(*a, **k)
    return wrapper
@deco
def hello():
    pass
print(hello.__name__)

def shout(f):
    def w(*a, **k):
        f(*a, **k).upper()
    return w
@shout
def greet():
    return "hi"
print(greet())

def a(f):
    return lambda: "a" + f()
def b(f):
    return lambda: "b" + f()
@a
@b
def x():
    return "x"
print(x())

def d(f):
    print("decorating")
    return f
@d
def g():
    print("running")

import functools
def count(f):
    @functools.wraps(f)
    def w(*a):
        w.n += 1
        return f(*a)
    w.n = 0
    return w
@count
def sq(x):
    return x * x
sq(2); sq(3)
print(sq.n, sq(4))

def double(x: int) -> int:
    return x * 2
print(double("ab"))
